#!/usr/bin/env bash
# Claude Code hook (generated by adapters/build.py from personas/*.yaml).
# SessionStart/UserPromptSubmit/SubagentStart accept plain stdout as context.
# The payload MUST stay under 10 KB — past it, Claude Code silently spills to
# a file and injects a ~2 KB preview instead. test.sh enforces the budget.
#
# Glob order IS the axis order: 00-doctrine, 01-essence-first, 02-say-less.
# --line emits the one-line reinforcement instead of the full bodies (full
# bodies on every prompt would stack one copy per turn into re-sent context).
set -uo pipefail

root="${CLAUDE_PLUGIN_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"

if [ "${1:-}" = "--line" ]; then
  echo "ON POINT ACTIVE — essence first (name the essence, verdict first, then the one next action), say less (terse, no filler). Substance, security and exact errors never compressed."
  exit 0
fi

cat "$root"/personas/*.md 2>/dev/null || true
